/*
 * NET_IO_$BOOT_DEVICE - record the device the node booted from
 *
 * Original address: 0x00E31C14
 * Size: 132 bytes (0x00E31C14 .. 0x00E31C97)
 * Generated by: Claude Opus 5.5
 *
 * Called once by OS_$INIT (0x00E33914), which stores the answer in
 * NETWORK_$DISKLESS.  Frame: (0x8,A6) boot_device word, (0xA,A6) boot_unit
 * word.  A Pascal function: Domain boolean in D0.b, TRUE when the boot
 * device is a network device.
 *
 * Blocks:
 *   0x00E31C1E-0x00E31C44  the network UIDs of the two software drivers:
 *                          NET_IO_$NIL_DRIVER gets NIL_$NETWORK_UID
 *                          (0xE1748C -> 0xE2453C), NET_IO_$USER_DRIVER gets
 *                          USER_$NETWORK_UID (0xE1749C -> 0xE2458C)
 *   0x00E31C46             result = TRUE (`st D0b')
 *   0x00E31C48-0x00E31C5E  device 2 or 3: boot_port_type = 0
 *   0x00E31C60-0x00E31C72  device 6: boot_port_type = 4
 *   0x00E31C74-0x00E31C86  device 8: boot_port_type = 5
 *   0x00E31C88             anything else: result = FALSE, nothing stored
 *   0x00E31C8C             the three network arms: boot_unit = the second
 *                          argument (NET_IO_UNWIRED +0x10)
 */

#include "net_io/net_io_internal.h"
#include "uid/uid.h"            /* NIL_$NETWORK_UID, USER_$NETWORK_UID */

/* Boot device codes the routine recognises (0x00E31C48-0x00E31C78) */
#define BOOT_DEVICE_NET_A       2
#define BOOT_DEVICE_NET_B       3
#define BOOT_DEVICE_NET_C       6
#define BOOT_DEVICE_NET_D       8

int8_t NET_IO_$BOOT_DEVICE(uint16_t boot_device, uint16_t boot_unit)
{
    int8_t diskless;                    /* D0.b */

    /* 0x00E31C1E-0x00E31C44 */
    NET_IO_$NIL_DRIVER[0].network_uid = NIL_$NETWORK_UID;
    NET_IO_$USER_DRIVER[0].network_uid = USER_$NETWORK_UID;

    /* 0x00E31C46 */
    diskless = -1;

    if (boot_device == BOOT_DEVICE_NET_A || boot_device == BOOT_DEVICE_NET_B) {
        /* 0x00E31C54-0x00E31C5E */
        NET_IO_UNWIRED.boot_port_type = 0;
    } else if (boot_device == BOOT_DEVICE_NET_C) {
        /* 0x00E31C66-0x00E31C72 */
        NET_IO_UNWIRED.boot_port_type = 4;
    } else if (boot_device == BOOT_DEVICE_NET_D) {
        /* 0x00E31C7A-0x00E31C86 */
        NET_IO_UNWIRED.boot_port_type = 5;
    } else {
        /* 0x00E31C88 */
        diskless = 0;
        return diskless;
    }

    /* 0x00E31C8C */
    NET_IO_UNWIRED.boot_unit = boot_unit;
    return diskless;
}
